package com.aistudyassistance.backend.dsa; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import jakarta.validation.Valid;
@RestController @RequestMapping("/api/dsa") public class DsaController{private final DsaRepository repo;public DsaController(DsaRepository r){repo=r;}@GetMapping("/problems")public List<DsaProblem> list(@RequestParam(required=false)String search,@RequestParam(required=false)String difficulty,@RequestParam(required=false)String status,@RequestParam(required=false)String revisionStatus,@RequestParam(required=false)String topic,@RequestParam(required=false)String platform){return repo.findAll().stream().filter(x->search==null||x.getTitle().toLowerCase().contains(search.toLowerCase())||x.getTopic().toLowerCase().contains(search.toLowerCase())||x.getPlatform().toLowerCase().contains(search.toLowerCase())).filter(x->difficulty==null||x.getDifficulty().equals(difficulty)).filter(x->status==null||x.getStatus().equals(status)).filter(x->revisionStatus==null||x.getRevisionStatus().equals(revisionStatus)).filter(x->topic==null||x.getTopic().equals(topic)).filter(x->platform==null||x.getPlatform().equals(platform)).sorted(Comparator.comparing(DsaProblem::getSolvedAt,Comparator.nullsLast(Comparator.reverseOrder()))).toList();}@PostMapping("/problems")@ResponseStatus(HttpStatus.CREATED)public DsaProblem create(@Valid@RequestBody DsaRequest r){return repo.save(new DsaProblem(r));}@PutMapping("/problems/{id}")public DsaProblem update(@PathVariable Long id,@Valid@RequestBody DsaRequest r){DsaProblem p=repo.findById(id).orElseThrow(()->new NoSuchElementException("Problem not found"));p.apply(r);return repo.save(p);}@DeleteMapping("/problems/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable Long id){repo.deleteById(id);}@GetMapping("/statistics")public Map<String,Object> stats(){var all=repo.findAll();return Map.of("total",all.size(),"solved",all.stream().filter(x->x.getStatus().equals("SOLVED")).count(),"inProgress",all.stream().filter(x->x.getStatus().equals("IN_PROGRESS")).count(),"reviewNeeded",all.stream().filter(x->x.getRevisionStatus().equals("REVIEW_NEEDED")).count(),"easy",all.stream().filter(x->x.getDifficulty().equals("EASY")).count(),"medium",all.stream().filter(x->x.getDifficulty().equals("MEDIUM")).count(),"hard",all.stream().filter(x->x.getDifficulty().equals("HARD")).count());}}
